/**
 * Downgrades organizations whose trial ended and emits `billing.plan_changed`.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Where an expired trial lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("trial-expiry-job");

/**
 * Moves expired trials down to the free plan and announces the change so the
 * audit log and any webhook subscriber see it.
 *
 * A tenant that outgrew the free limits during the trial is left alone and
 * logged instead: silently downgrading them would put their workspace over
 * quota, and every subsequent write would fail with no explanation.
 */
export async function runTrialExpiryJob(now: Date): Promise<JobResult> {
  return runJob("trial-expiry", async (result) => {
    const stamp = toIsoTimestamp(now);
    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
    const freeLimits = getPlanLimits(FALLBACK_PLAN);

    for (const subscription of expiring) {
      const orgId = subscription.orgId as OrgId;
      const usage = await usageRepo.getUsage(orgId);

      if (
        usage.seatsUsed > freeLimits.seats ||
        usage.projectsUsed > freeLimits.projects
      ) {
        result.failed += 1;
        logger.warn("trial expired but tenant is over the free plan", {
          orgId,
          seats: usage.seatsUsed,
          projects: usage.projectsUsed,
        });
        continue;
      }

      await subscriptionRepo.updateSubscriptionPlan(
        orgId,
        FALLBACK_PLAN,
        subscription.interval,
      );

      await emit("billing.plan_changed", {
        orgId,
        actorId: null,
        occurredAt: stamp,
        from: subscription.plan,
        to: FALLBACK_PLAN,
      });

      result.processed += 1;
    }
  });
}
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
"use server";

/**
 * Changes plan; refuses a downgrade that would breach a current quota.
 *
 * Owner D. The interesting case is the *downgrade*: the target plan's limits
 * are compared against today's usage before the switch, so an org on growth
 * with 40 seats cannot silently drop to starter and strand 37 people.
 *
 * Must call (do not reimplement): changePlanSchema, can, getPlanLimits,
 * wouldExceedLimit, getActor, toActionResult
 */

import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { changePlanSchema, type ChangePlanInput } from "@/schemas/billing";
import { changePlan } from "@/server/services/billing-service";
import { getUsage } from "@/server/services/usage-service";
import type { ActionResult } from "@/types/api";
import type { LimitedResource, Subscription } from "@/types/billing";
import type { Actor } from "@/types/member";

const run = withAction<typeof changePlanSchema, Subscription>(
  changePlanSchema,
  async (raw, actor) => {
    const input = raw as ChangePlanInput;

    if (!can(actor, "org:manage_billing", { kind: "billing", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:manage_billing");
    }

    await assertPlanFitsCurrentUsage(actor, input);

    const subscription = await changePlan(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return subscription;
  },
  { revalidate: ["billing"], cacheProfile: "hours" },
);

/**
 * Compares live usage against the *target* plan. `wouldExceedLimit` is called
 * with a requested delta of zero: we are not consuming anything, only asking
 * whether what is already in use still fits.
 */
async function assertPlanFitsCurrentUsage(
  actor: Actor,
  input: ChangePlanInput,
): Promise<void> {
  const usage = await getUsage(actor, input.orgId);
  const limits = getPlanLimits(input.plan);

  const consumption: ReadonlyArray<readonly [LimitedResource, number]> = [
    ["seats", usage.seatsUsed],
    ["projects", usage.projectsUsed],
    ["storageMb", usage.storageMbUsed],
  ];

  for (const [resource, used] of consumption) {
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new PlanLimitError(resource, limits[resource], used);
    }
  }
}

export async function changePlanAction(raw: unknown): Promise<ActionResult<Subscription>> {
  return run(raw);
}
/**
 * Current usage and limit checks for one organization.
 *
 * Owner D. Returns the raw counters *and* the plan ceilings side by side, so a
 * dashboard can render a meter without knowing the plan table itself.
 *
 * Must call (do not reimplement): can, assertOrgScope, getPlanLimits
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getPlanLimits } from "@/config/plan-limits";
import { requireActorFor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { orgIdSchema } from "@/schemas/common";
import { checkLimit } from "@/server/services/billing-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { getUsage } from "@/server/services/usage-service";
import type { LimitedResource } from "@/types/billing";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ orgId: string }> };

const REPORTED: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  void request;

  try {
    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { orgId } = await context.params;
    const parsed = orgIdSchema.safeParse(orgId);
    if (!parsed.success) {
      return failure("validation_failed", "Malformed organization id.");
    }

    const actor = await requireActorFor(parsed.data);
    assertOrgScope(actor, parsed.data);

    if (!can(actor, "org:read", { kind: "organization", orgId: parsed.data })) {
      return failure("forbidden", "You cannot read this organization.");
    }

    const [{ organization }, usage] = await Promise.all([
      getOrganizationSummary(actor, parsed.data),
      getUsage(actor, parsed.data),
    ]);

    const limits = getPlanLimits(organization.plan);
    const checks = await Promise.all(
      REPORTED.map((resource) => checkLimit(parsed.data, resource, 0)),
    );

    return Response.json({ plan: organization.plan, limits, usage, checks });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

