cat > tests/services/tmp-storage.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as attachmentService from "@/server/services/attachment-service";
import * as issueService from "@/server/services/issue-service";
import * as billingService from "@/server/services/billing-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
const MB = 1024 * 1024;
describe("tmp", () => {
  it("works", async () => {
    const t = await createTenant("tmp-s", "starter");
    const t2 = await createTenant("tmp-s2", "starter");
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id));
    const a = await attachmentService.addAttachment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, filename: "a", contentType: "text/plain", sizeBytes: Math.floor(0.4 * MB) });
    const b = await attachmentService.addAttachment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, filename: "b", contentType: "text/plain", sizeBytes: Math.floor(2.5 * MB) });
    expect((await billingService.checkLimit(t.org.id, "storageMb", 0)).used).toBe(4);
    expect((await usageRepo.recomputeUsage(t.org.id)).storageMbUsed).toBe(4);
    await issueRepo.archiveIssue?.(t.org.id, issue.id, t.userIds.owner as never).catch(() => {});
    await expect(attachmentService.removeAttachment(t2.actors.owner, { orgId: t2.org.id, attachmentId: a.id })).rejects.toThrow(/not found/);
    await attachmentService.removeAttachment(t.actors.owner, { orgId: t.org.id, attachmentId: a.id });
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(3);
    await expect(attachmentService.removeAttachment(t.actors.owner, { orgId: t.org.id, attachmentId: a.id })).rejects.toThrow(/not found/);
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(3);
    expect((await usageRepo.recomputeUsage(t.org.id)).storageMbUsed).toBe(3);
  });
});
EOF
npx vitest run tests/services/tmp-storage.test.ts 2>&1 | tail -30

